import React, { useState } from 'react';

const QuizPage = () => {
        const [formData, setFormData] = useState({
                subject: "",
                exam: "",
                difficultyLevels: [],
        });

        // A function to handle input changes for both fields
        const handleChange = (e) => {
                const { name, value } = e.target;
                setFormData((prevData) => ({
                        ...prevData,
                        [name]: value,
                }));
        };

        return (
                <div>
                        <form>

                                <h3>Enter subject</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. Maths, Physics"
                                        name="subject"
                                        value={formData.subject}
                                        onChange={handleChange}
                                />

                                <h3>Exam Name</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. MidTerm, JEE"
                                        name="exam"
                                        value={formData.exam}
                                        onChange={handleChange}
                                />

<label className="block font-semibold">Select Difficulty Levels</label>
          <div>
            <label>
              <input
                type="checkbox"
                value="Easy"
                checked={formData.difficultyLevels.includes('Easy')}
                onChange={handleDifficultyChange}
              />
              Easy
            </label>
            <label>
              <input
                type="checkbox"
                value="Medium"
                checked={formData.difficultyLevels.includes('Medium')}
                onChange={handleDifficultyChange}
              />
              Medium
            </label>
            <label>
              <input
                type="checkbox"
                value="Hard"
                checked={formData.difficultyLevels.includes('Hard')}
                onChange={handleDifficultyChange}
              />
              Hard
            </label>
          </div>

                        </form>
                </div>
        );
};

export default QuizPage;
